import subprocess, json, os, tempfile
def export_content(content):
    with tempfile.NamedTemporaryFile(mode='w', suffix='.sh', delete=False) as tf:
        tf.write(content)
        tf.write('
eval "$(argc --argc-eval "$0" "$@")"
')
        name=tf.name
    try:
        out=subprocess.run(["./executable","--argc-export",name], stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
        if out.returncode!=0:
            print(f"ERR {content.strip()}: {out.stderr[:500]}")
            return None
        return json.loads(out.stdout)
    finally:
        os.unlink(name)

