# Minimal parser implementation (simplified)
# For now we will implement only enough to pass the provided examples? But we need full.
# Due to time, we will attempt to implement a parser that uses original binary to get JSON? No, that's not allowed for final executable? The rule says our final solution must not depend on original binary. But we can use original binary during development to test, but our final executable must be independent. So we must write our own parser, but we can use original binary as reference during development.

# For this initial version, we will implement a very simplified version that still attempts to handle basic cases.

# We need to re-implement parsing from scratch.

# To keep things manageable, we will implement a parser that handles:

# - @describe, @meta, @cmd, @alias, @flag, @option, @arg, @env

# We'll reuse helper functions for splitting name and suffix from earlier prototype.

import re

def split_name_and_suffix(token):
    token = token.strip()
    if not token:
        return "", ""
    m = re.match(r'^([\-+]+[A-Za-z0-9_]+(?:[-_][A-Za-z0-9_]+)*)', token)
    if m:
        base = m.group(1)
        suffix = token[len(base):]
        return base, suffix
    m = re.match(r'^([A-Za-z0-9_]+(?:[-_][A-Za-z0-9_]+)*)', token)
    if m:
        base = m.group(1)
        suffix = token[len(base):]
        return base, suffix
    return token, ""

def parse_suffix(suffix):
    prefixed = False
    assigned = False
    required = False
    multiple_occurs = False
    delimiter = None
    terminated = False
    default = None
    choice = None
    s = suffix
    if s.startswith('-'):
        prefixed = True
        s = s[1:]
    if s.startswith(':'):
        assigned = True
        s = s[1:]
    idx=0
    while idx < len(s):
        ch=s[idx]
        if ch=='!':
            required=True
            idx+=1
        elif ch=='+':
            required=True
            multiple_occurs=True
            idx+=1
        elif ch=='*':
            multiple_occurs=True
            idx+=1
        elif ch==',':
            delimiter=','
            idx+=1
        elif ch=='~':
            terminated=True
            idx+=1
        else:
            break
    s=s[idx:]
    # default: starts with "="
    if s.startswith('='):
        bracket_idx=s.find('[')
        if bracket_idx!=-1:
            default_part=s[1:bracket_idx]
            if default_part:
                if default_part.startswith('`') and default_part.endswith('`'):
                    default={"type":"Fn","value":default_part[1:-1]}
                else:
                    default={"type":"Value","value":default_part}
            s=s[bracket_idx:]
        else:
            default_part=s[1:]
            if default_part.startswith('`') and default_part.endswith('`'):
                default={"type":"Fn","value":default_part[1:-1]}
            else:
                default={"type":"Value","value":default_part}
            s=""
    # choice
    if s.startswith('['):
        end_idx=s.find(']')
        if end_idx!=-1:
            inner=s[1:end_idx]
            # parse inner
            # handle leading = and ?
            if inner.startswith('='):
                # default + choices
                rest=inner[1:]
                parts=rest.split('|')
                if parts:
                    default={"type":"Value","value":parts[0]}
                    choice={"type":"Values","data":parts}
            elif '`' in inner:
                m=re.match(r'^(\?)?`([^`]+)`$', inner)
                if m:
                    q=m.group(1)
                    fn=m.group(2)
                    choice={"type":"Fn","data":[fn, False if q else True]}
                else:
                    # maybe value list?
                    if '|' in inner:
                        parts=inner.split('|')
                        choice={"type":"Values","data":parts}
            else:
                if '|' in inner:
                    parts=inner.split('|')
                    choice={"type":"Values","data":parts}
                elif inner:
                    choice={"type":"Values","data":[inner]}
            s=s[end_idx+1:]
    return {
        "prefixed": prefixed,
        "assigned": assigned,
        "required": required,
        "multiple_occurs": multiple_occurs,
        "delimiter": delimiter,
        "terminated": terminated,
        "default": default,
        "choice": choice,
        "remaining": s,
    }

def parse_notation_token(tok):
    if tok.startswith('<') and tok.endswith('>'):
        return tok[1:-1]
    return tok

def compute_id(long_name):
    if not long_name:
        return ""
    is_plus = long_name.startswith('+')
    stripped = long_name.lstrip('-+')
    stripped = stripped.replace('-', '_')
    if is_plus:
        return "plus_" + stripped
    return stripped

def notation_min_max(notation):
    # notation like "VALUE*", "FILE+", "VALUE?", "OXA~", "FILE", etc.
    s=notation
    if s.endswith('*'):
        return 0, 32767
    if s.endswith('+'):
        return 1, 32767
    if s.endswith('?'):
        return 0, 1
    if s.endswith('~'):
        return 1, 32767
    return 1,1

# Data structures simplified
class FlagOption:
    def __init__(self, **kwargs):
        self.id=kwargs.get('id')
        self.long_name=kwargs.get('long_name')
        self.short_name=kwargs.get('short_name')
        self.flag=kwargs.get('flag', False)
        self.describe=kwargs.get('describe','')
        self.notations=kwargs.get('notations', [])
        self.required=kwargs.get('required', False)
        self.multiple_occurs=kwargs.get('multiple_occurs', False)
        self.multiple_values=kwargs.get('multiple_values', False)
        self.num_args=kwargs.get('num_args', [0,0] if kwargs.get('flag') else [1,1])
        self.delimiter=kwargs.get('delimiter')
        self.terminated=kwargs.get('terminated', False)
        self.prefixed=kwargs.get('prefixed', False)
        self.assigned=kwargs.get('assigned', False)
        self.default=kwargs.get('default')
        self.choice=kwargs.get('choice')
        self.env=kwargs.get('env')
        self.inherited=kwargs.get('inherited', False)

class Positional:
    def __init__(self, **kwargs):
        self.id=kwargs.get('id')
        self.describe=kwargs.get('describe','')
        self.notation=kwargs.get('notation','VAL')
        self.required=kwargs.get('required', False)
        self.multiple=kwargs.get('multiple', False)
        self.delimiter=kwargs.get('delimiter')
        self.terminated=kwargs.get('terminated', False)
        self.default=kwargs.get('default')
        self.choice=kwargs.get('choice')
        self.env=kwargs.get('env')

class Env:
    def __init__(self, **kwargs):
        self.id=kwargs.get('id')
        self.describe=kwargs.get('describe','')
        self.required=kwargs.get('required', False)
        self.default=kwargs.get('default')
        self.choice=kwargs.get('choice')
        self.inherited=kwargs.get('inherited', False)

class Command:
    def __init__(self, name='', describe='', version=None):
        self.name=name
        self.describe=describe
        self.version=version
        self.aliases=[]
        self.flag_options=[]
        self.positionals=[]
        self.envs=[]
        self.subcommands={}  # name -> Command
        self.subcommands_list=[]
        self.command_fn=None
        self.metadata={}
        self.require_tools=[]
        self.dotenv=None
        self.combine_shorts=False
        self.inherit_flag_options=False
        self.default_subcommand=False
        self.symbol=None
        # For parsing, temporary storage of flag_options that are inherited etc.

def parse_file(file_path):
    with open(file_path, 'r', encoding='utf-8', errors='ignore') as f:
        content=f.read()
    lines=content.splitlines()
    funcs={}
    # extract functions
    func_def_re=re.compile(r'^\s*(?:function\s+)?([A-Za-z_][A-Za-z0-9_:]*)\s*\(\)\s*\{?')
    i=0
    while i < len(lines):
        line=lines[i]
        m=func_def_re.match(line)
        if m:
            name=m.group(1)
            idx=line.find('{', m.end()-1)
            if idx!=-1:
                brace=1
                for ch in line[idx+1:]:
                    if ch=='{':
                        brace+=1
                    elif ch=='}':
                        brace-=1
                if brace==0:
                    start=idx+1
                    end=line.rfind('}')
                    funcs[name]=line[start:end]
                    i+=1
                    continue
                else:
                    body_parts=[line[idx+1:]]
                    j=i+1
                    while j < len(lines) and brace>0:
                        l=lines[j]
                        for ch in l:
                            if ch=='{':
                                brace+=1
                            elif ch=='}':
                                brace-=1
                        if brace==0:
                            last_idx=l.rfind('}')
                            body_parts.append(l[:last_idx])
                            break
                        else:
                            body_parts.append(l)
                        j+=1
                    funcs[name]="\n".join(body_parts)
                    i=j+1
                    continue
        i+=1

    basename=os.path.basename(file_path)
    if basename.endswith('.sh'):
        basename=basename[:-3]
    root=Command(name=basename, describe='', version=None)
    pending=None

    def collect_continuation(start_idx):
        cont=[]
        j=start_idx
        while j < len(lines):
            l=lines[j]
            stripped=l.lstrip()
            if not stripped.startswith('#'):
                break
            after=stripped[1:].lstrip() if stripped.startswith('#') else stripped
            if after.startswith('@'):
                break
            cont.append(after)
            j+=1
        return cont, j

    i=0
    while i < len(lines):
        line=lines[i]
        tag_match=re.match(r'^\s*#\s*@(\w+)(.*)$', line)
        if tag_match:
            tag=tag_match.group(1)
            rest=tag_match.group(2).strip()
            cont, nxt=collect_continuation(i+1)
            if tag=='describe':
                target=pending if pending else root
                # combine rest + cont
                long_lines=cont[:]
                while long_lines and long_lines[0].strip()=="":
                    long_lines.pop(0)
                while long_lines and long_lines[-1].strip()=="":
                    long_lines.pop()
                long_clean="\n".join(long_lines)
                if rest and long_clean:
                    target.describe=rest+"\n\n"+long_clean
                elif rest:
                    target.describe=rest
                else:
                    target.describe=long_clean
                i=nxt
                continue
            elif tag=='meta':
                target=pending if pending else root
                if not rest:
                    i=nxt if cont else i+1
                    continue
                parts=rest.split(None,1)
                key=parts[0]
                value=parts[1] if len(parts)>1 else ""
                target.metadata[key]=value if value else None
                if key=='version':
                    target.version=value
                elif key=='dotenv':
                    target.dotenv=value if value else ".env"
                elif key=='combine-shorts':
                    target.combine_shorts=True
                elif key=='inherit-flag-options':
                    target.inherit_flag_options=True
                elif key=='require-tools':
                    tools=[t.strip() for t in value.split(',') if t.strip()]
                    target.require_tools.extend(tools)
                elif key=='default-subcommand':
                    target.default_subcommand=True
                elif key=='symbol':
                    target.symbol=value
                i=nxt if cont else i+1
                continue
            elif tag=='cmd':
                pending=Command(name='', describe=rest)
                if cont:
                    long_lines=cont[:]
                    while long_lines and long_lines[0].strip()=="":
                        long_lines.pop(0)
                    while long_lines and long_lines[-1].strip()=="":
                        long_lines.pop()
                    long_clean="\n".join(long_lines)
                    if rest and long_clean:
                        pending.describe=rest+"\n\n"+long_clean
                    elif long_clean:
                        pending.describe=long_clean
                    else:
                        pending.describe=rest
                i=nxt
                continue
            elif tag=='alias':
                aliases=[]
                for part in rest.split(','):
                    for sub in part.strip().split():
                        if sub:
                            aliases.append(sub)
                if pending:
                    pending.aliases.extend(aliases)
                else:
                    root.aliases.extend(aliases)
                i=nxt if cont else i+1
                continue
            elif tag in ('flag','option','arg','env'):
                # For these tags, rest contains definition plus maybe description, cont is long description
                # We need to parse based on tag
                tokens=rest.split()
                if not tokens:
                    i=nxt if cont else i+1
                    continue
                if tag in ('flag','option'):
                    # collect name tokens
                    name_tokens=[]
                    idx=0
                    while idx < len(tokens):
                        tok=tokens[idx]
                        if tok.startswith('-') or tok.startswith('+'):
                            name_tokens.append(tok)
                            idx+=1
                        else:
                            break
                    remaining=tokens[idx:]
                    env=None
                    notations=[]
                    desc_tokens=[]
                    j=0
                    while j < len(remaining):
                        rt=remaining[j]
                        if rt=='$$':
                            env='auto'
                            j+=1
                        elif rt.startswith('$'):
                            env=rt[1:] if rt!='$$' else 'auto'
                            j+=1
                        elif rt.startswith('<') and rt.endswith('>'):
                            notations.append(parse_notation_token(rt))
                            j+=1
                        else:
                            desc_tokens=remaining[j:]
                            break
                    desc=" ".join(desc_tokens)
                    # Add continuation
                    if cont:
                        long_lines=cont[:]
                        while long_lines and long_lines[0].strip()=="":
                            long_lines.pop(0)
                        while long_lines and long_lines[-1].strip()=="":
                            long_lines.pop()
                        long_clean="\n".join(long_lines)
                        if desc and long_clean:
                            desc=desc+"\n"+long_clean
                        elif long_clean:
                            desc=long_clean
                    # parse name_tokens
                    bases=[]
                    combined_mods={"prefixed":False,"assigned":False,"required":False,"multiple_occurs":False,"delimiter":None,"terminated":False,"default":None,"choice":None}
                    for nt in name_tokens:
                        base,suf=split_name_and_suffix(nt)
                        mods=parse_suffix(suf)
                        bases.append(base)
                        # merge
                        for k in ("prefixed","assigned","required","multiple_occurs","terminated"):
                            if mods[k]:
                                combined_mods[k]=True
                        if mods["delimiter"]:
                            combined_mods["delimiter"]=mods["delimiter"]
                        if mods["default"]:
                            combined_mods["default"]=mods["default"]
                        if mods["choice"]:
                            combined_mods["choice"]=mods["choice"]
                    long_name=None
                    short_name=None
                    if len(bases)==1:
                        long_name=bases[0]
                    elif len(bases)>=2:
                        short_name=bases[0]
                        long_name=bases[1]
                    else:
                        long_name=name_tokens[0]
                    id_ = compute_id(long_name) if long_name else ""
                    final_env=None
                    if env=='auto':
                        final_env=id_.upper()
                    elif env:
                        final_env=env
                    # default notations
                    if not notations and tag=='option':
                        # default notation id.upper() plus maybe "~" if terminated
                        if combined_mods["terminated"]:
                            notations=[id_.upper()+"~"]
                        else:
                            notations=[id_.upper()]
                    # compute num_args from notations
                    # For flag, [0,0]
                    if tag=='flag':
                        num_args=[0,0]
                        multiple_values=combined_mods["multiple_occurs"]
                    else:
                        # option
                        # compute min/max from notations
                        total_min=0
                        total_max=0
                        has_inf=False
                        for n in notations:
                            mn,mx=notation_min_max(n)
                            total_min+=mn
                            if mx>=32767:
                                has_inf=True
                            else:
                                total_max+=mx
                        if has_inf:
                            total_max=32767
                        if total_min==0 and total_max==0:
                            # default 1,1 ?
                            total_min=1
                            total_max=1
                        num_args=[total_min,total_max]
                        multiple_values = (total_max>1) or combined_mods["multiple_occurs"] or (len(notations)>1)
                    # create FlagOption
                    fo=FlagOption(
                        id=id_,
                        long_name=long_name,
                        short_name=short_name,
                        flag=(tag=='flag'),
                        describe=desc,
                        notations=notations,
                        required=combined_mods["required"],
                        multiple_occurs=combined_mods["multiple_occurs"],
                        multiple_values=multiple_values,
                        num_args=num_args,
                        delimiter=combined_mods["delimiter"],
                        terminated=combined_mods["terminated"],
                        prefixed=combined_mods["prefixed"],
                        assigned=combined_mods["assigned"],
                        default=combined_mods["default"],
                        choice=combined_mods["choice"],
                        env=final_env,
                        inherited=False,
                    )
                    fo.id=id_
                    target=pending if pending else root
                    target.flag_options.append(fo)
                    i=nxt
                    continue
                elif tag=='arg':
                    # first token is arg definition
                    def_token=tokens[0]
                    base,suf=split_name_and_suffix(def_token)
                    mods=parse_suffix(suf)
                    remaining=tokens[1:]
                    env=None
                    notation=None
                    desc_tokens=[]
                    j=0
                    while j < len(remaining):
                        rt=remaining[j]
                        if rt=='$$':
                            env='auto'
                            j+=1
                        elif rt.startswith('$'):
                            env=rt[1:]
                            j+=1
                        elif rt.startswith('<') and rt.endswith('>'):
                            notation=parse_notation_token(rt)
                            j+=1
                        else:
                            desc_tokens=remaining[j:]
                            break
                    desc=" ".join(desc_tokens)
                    if cont:
                        long_lines=cont[:]
                        while long_lines and long_lines[0].strip()=="":
                            long_lines.pop(0)
                        while long_lines and long_lines[-1].strip()=="":
                            long_lines.pop()
                        long_clean="\n".join(long_lines)
                        if desc and long_clean:
                            desc=desc+"\n"+long_clean
                        elif long_clean:
                            desc=long_clean
                    id_=base
                    final_env=None
                    if env=='auto':
                        final_env=id_.upper()
                    elif env:
                        final_env=env
                    # notation handling: if not provided, default is id.upper()
                    if not notation:
                        notation=id_.upper()
                    # Determine required, multiple, terminated, etc from mods
                    required=mods["required"]
                    # For arg, "*" means multiple, "+" required multiple
                    multiple=mods["multiple_occurs"]  # for arg, * or + indicates multiple
                    # But need to differentiate: For arg, suffix "*" means multiple but not required? Actually val* => multiple True, required False
                    # val+ => multiple True, required True
                    # val! => required True
                    # So we have: if suffix contains "+" => required True and multiple True
                    # if "*" => multiple True
                    # if "!" => required True
                    # We have mods["required"] and multiple_occurs as indicators
                    # For val* case: mods required False, multiple_occurs True => multiple True, required False
                    # For val+ case: required True, multiple_occurs True => multiple True, required True
                    # For val! case: required True, multiple_occurs False => multiple False, required True
                    # So:
                    multiple=mods["multiple_occurs"]
                    required=mods["required"]
                    terminated=mods["terminated"]
                    delimiter=mods["delimiter"]
                    # For arg with "~" terminated
                    # For arg with default and choice
                    default=mods["default"]
                    choice=mods["choice"]
                    # For notation, if it has *+? etc, need to adjust? But arg definition may also have notation like "<FILE>" separate, but we already have notation variable.
                    # For arg, if terminated, multiple should be True? In export, vals~ had multiple True, terminated True.
                    if terminated:
                        multiple=True
                    # Create Positional
                    # Determine if positional has multiple from notation? For notation with *+ etc, multiple? But our notation for arg is single, not list. For simplicity, if notation ends with *+ etc, set multiple?
                    # We'll check if notation ends with *+~ etc
                    if notation:
                        if notation.endswith('*') or notation.endswith('+') or notation.endswith('~'):
                            multiple=True
                    pos=Positional(
                        id=id_,
                        describe=desc,
                        notation=notation,
                        required=required,
                        multiple=multiple,
                        delimiter=delimiter,
                        terminated=terminated,
                        default=default,
                        choice=choice,
                        env=final_env,
                    )
                    target=pending if pending else root
                    target.positionals.append(pos)
                    i=nxt
                    continue
                elif tag=='env':
                    def_token=tokens[0]
                    base,suf=split_name_and_suffix(def_token)
                    mods=parse_suffix(suf)
                    desc_tokens=tokens[1:]
                    desc=" ".join(desc_tokens)
                    if cont:
                        long_lines=cont[:]
                        while long_lines and long_lines[0].strip()=="":
                            long_lines.pop(0)
                        while long_lines and long_lines[-1].strip()=="":
                            long_lines.pop()
                        long_clean="\n".join(long_lines)
                        if desc and long_clean:
                            desc=desc+"\n"+long_clean
                        elif long_clean:
                            desc=long_clean
                    id_=base
                    required=mods["required"]
                    default=mods["default"]
                    choice=mods["choice"]
                    e=Env(id=id_, describe=desc, required=required, default=default, choice=choice, inherited=False)
                    target=pending if pending else root
                    target.envs.append(e)
                    i=nxt
                    continue
        # Check for function definition
        func_match=func_def_re.match(line)
        if func_match:
            fname=func_match.group(1)
            # If pending exists, finalize it as subcommand
            if pending:
                # Determine name and parent path
                parts=fname.split('::')
                cmd_name=parts[-1]
                # For command name, we should keep original function name? Actually export shows name is last part, but with underscores? For cmd_alias, name "cmd_alias" (function name). So cmd_name is parts[-1] (could have underscores)
                pending.name=cmd_name
                pending.command_fn=fname
                # Generate automatic alias: if command name contains "_", add hyphenated version as alias if not already? Let's check: For cmd_alias, alias includes "cmd-alias" automatically plus explicit "a". So we should generate hyphenated alias from cmd_name replacing "_" with "-"
                auto_alias=cmd_name.replace('_','-')
                if auto_alias!=cmd_name and auto_alias not in pending.aliases:
                    # Insert at beginning? In export for cmd_alias, aliases were ["cmd-alias","a"] – auto first, then explicit. So we should put auto first.
                    pending.aliases=[auto_alias]+pending.aliases
                # Now insert into tree
                # Build parent path
                parent=root
                for part in parts[:-1]:
                    # part is parent command name
                    # Find existing subcommand with name part
                    if part not in parent.subcommands:
                        # Create intermediate parent command if not exists? For builder::ls case, builder must exist before ls? In earlier test, we required parent to exist, else error "lack of parent command". So we should check if parent exists, if not, error? For our implementation, we will create parent if not exists but mark command_fn None.
                        new_parent=Command(name=part, describe='', version=None)
                        new_parent.command_fn=None
                        parent.subcommands[part]=new_parent
                        parent.subcommands_list.append(new_parent)
                    parent=parent.subcommands[part]
                # Now add pending as subcommand of parent
                # If command with same name already exists? Overwrite?
                if cmd_name in parent.subcommands:
                    # Merge? But for simplicity replace?
                    # Actually if there are two commands with same name (should not), we replace
                    # Remove from list
                    parent.subcommands_list=[sc for sc in parent.subcommands_list if sc.name!=cmd_name]
                parent.subcommands[cmd_name]=pending
                parent.subcommands_list.append(pending)
                pending=None
            else:
                # No pending, check if function is main
                if fname=='main':
                    root.command_fn='main'
            i+=1
            continue
        i+=1

    # After parsing, we have root
    # For root, we need to add help and version flag_options automatically? In export, they have help and version.
    # Let's add them if not present
    # Check if root already has help/version? In examples, they are auto-added.
    # For each command (including root and subcommands), we should ensure help flag exists.

    def ensure_help_version(cmd):
        has_help=False
        has_version=False
        for fo in cmd.flag_options:
            if fo.long_name=='--help':
                has_help=True
            if fo.long_name=='--version':
                has_version=True
        if not has_help:
            fo=FlagOption(id='help', long_name='--help', short_name='-h', flag=True, describe='Print help' if cmd!=root else '')
            # Actually for root, describe for help/version? In export, root's help/version had empty describe when no version meta? But when version meta present, describe "Print help" and "Print version"? Let's check: For multiline with version 1.0.0, root's help had describe "Print help", version "Print version". For demo root, help/version describe empty? Actually demo root's help/version had empty describe? In earlier export for demo root, help had describe "", version describe "". But for subcommands, help had describe ""? Wait for upload, help had ""? For download, help had "Print help". So inconsistent.
            # For simplicity, we will set describe "" for help/version unless version meta present.
            # We'll set later based on version? Let's set empty for now, but for version meta present, set "Print help" and "Print version".
            # Actually in export for multiline root (version 1.0.0) help describe "Print help", version "Print version".
            # For envs root (no version), help/version describe "".
            # So rule: If command has version not None, help/version describe "Print help"/"Print version", else "".
            # For subcommands, help always? In demo subcommands, help had "" for upload, but "Print help" for download? Let's check: earlier export for demo upload help had "" (no describe), for download help had "Print help". Why difference? Because download has options, so help description is "Print help"? For upload with no options, help description ""?
            # Let's not overcomplicate: We will set help describe to "" for all, but for commands that have flag_options (options) we set "Print help"? Hmm.
            # Let's check pattern: For command with no options (like cmd in args), help describe "".
            # For command with options (like download), help describe "Print help".
            # Similarly for flags command (which has options), help describe ""? In options/flags command, help had ""? Actually for options subcommand, its flag_options include help with ""? Let's check earlier: options subcommand's help had "" (since we printed only few). For flags subcommand, help had ""? In export for options, we saw for subcommands, help had ""? For flags subcommand, help had ""? In earlier export snippet for options, we saw for subcommand "options" flag_options included help with ""? Actually we printed only first few but we saw help "".
            # For strict root which has options, help had "Print help"? Let's check: strict help earlier had "Print help" for help? Actually strict usage showed "Print help" for help? The USAGE for strict showed:
            # OPTIONS:
            #   -h, --help        Print help
            #   -V, --version     Print version
            # So help had "Print help", version "Print version" for strict root (which has options). For args cmd (no options), help had "".
            # So rule might be: For command that has flag_options besides help/version, its help option has describe "Print help" and version "Print version". For command without options, help describe "".
            # Let's implement: If command has any flag_options besides help/version, then help describe "Print help", version "Print version" if version meta present? Actually version describe also "Print version" when command has version? Not sure.

            # For now we'll just create help and version with empty describe initially, and later adjust in help generation.

            pass

    # We'll ensure help/version for all commands recursively
    def add_help_version_recursive(cmd, is_root=False):
        # Check existing
        has_help = any(fo.long_name=='--help' for fo in cmd.flag_options)
        has_version = any(fo.long_name=='--version' for fo in cmd.flag_options)
        if not has_help:
            # Determine describe
            # For root, if version is not None, describe "Print help", else ""? But also if has other options?
            # Let's check: For root with version (multiline) help was "Print help"
            # For root without version but with options (strict) help was "Print help" (since it had options)
            # For root with subcommands only (demo) help had "".
            # So for help describe: if cmd.flag_options (excluding help/version) non-empty or cmd.positionals non-empty or cmd.version is not None, then "Print help", else "".
            # Actually for demo root, which has subcommands but no flag_options/positionals, help was "".
            # For args root which has many subcommands, help "".
            # For strict root which has flag_options, help "Print help".
            # For multiline root which has flag_options and positionals and subcommands, help "Print help".
            # So logic: If cmd has any flag_options (excluding help/version) or positionals, then help describe "Print help", else "".
            # For subcommands like upload (no flag_options besides help), help "".
            # For download (has flag_options), help "Print help".
            # So implement that.
            has_other_options = any(fo.long_name not in ('--help','--version') for fo in cmd.flag_options)
            has_pos = len(cmd.positionals)>0
            if has_other_options or has_pos or (cmd.version is not None):
                desc_help = "Print help"
            else:
                desc_help = ""
            fo_help=FlagOption(id='help', long_name='--help', short_name='-h', flag=True, describe=desc_help, notations=[], required=False, multiple_occurs=False, multiple_values=False, num_args=[0,0], delimiter=None, terminated=False, prefixed=False, assigned=False, default=None, choice=None, env=None, inherited=False)
            fo_help.id='help'
            cmd.flag_options.append(fo_help)
        if is_root:
            # version only for root? Actually subcommands also have help but not version? In examples, subcommands like upload have only help, not version. In export, subcommands have only help. Root has help and version.
            # In strict root (no subcommands) has both help and version.
            # In multiline root (has subcommands) has both help and version.
            # In demo root (has subcommands) has help and version.
            # So root: has both help and version, subcommands: only help (unless version meta? For version meta, subcommands may still only have help)
            # Let's add version only for root
            if not has_version:
                desc_version = "Print version" if (cmd.version is not None or any(fo.long_name not in ('--help','--version') for fo in cmd.flag_options) or len(cmd.positionals)>0) else ""
                # For demo root, version describe "" (no options), for strict root version "Print version" (has options), for multiline root "Print version" (has options)
                fo_ver=FlagOption(id='version', long_name='--version', short_name='-V', flag=True, describe=desc_version, notations=[], required=False, multiple_occurs=False, multiple_values=False, num_args=[0,0], delimiter=None, terminated=False, prefixed=False, assigned=False, default=None, choice=None, env=None, inherited=False)
                fo_ver.id='version'
                cmd.flag_options.append(fo_ver)
        # Recurse for subcommands
        for sc in cmd.subcommands_list:
            add_help_version_recursive(sc, is_root=False)

    add_help_version_recursive(root, is_root=True)

    # Handle inherit-flag-options: If root has inherit_flag_options True, then each subcommand should inherit root's flag_options (excluding help/version) as inherited.
    # In earlier example inherit-flag-options, root had --user, --no-pager, -t/--type, --state. Subcommands start and stop had those options plus their own positionals and help.
    # So we need to copy root's flag_options to subcommands as inherited.

    def inherit_flags(cmd, parent_flags):
        # parent_flags includes all flag_options from parent that should be inherited (excluding help/version?)
        # For each subcommand, add inherited flags that don't already exist (by long_name)
        for sc in cmd.subcommands_list:
            # For sc, add parent_flags that are not already present (by long_name)
            existing_longs=set(fo.long_name for fo in sc.flag_options)
            for pfo in parent_flags:
                if pfo.long_name not in existing_longs:
                    # clone
                    new_fo=FlagOption(
                        id=pfo.id,
                        long_name=pfo.long_name,
                        short_name=pfo.short_name,
                        flag=pfo.flag,
                        describe=pfo.describe,
                        notations=pfo.notations[:],
                        required=pfo.required,
                        multiple_occurs=pfo.multiple_occurs,
                        multiple_values=pfo.multiple_values,
                        num_args=pfo.num_args[:],
                        delimiter=pfo.delimiter,
                        terminated=pfo.terminated,
                        prefixed=pfo.prefixed,
                        assigned=pfo.assigned,
                        default=pfo.default,
                        choice=pfo.choice,
                        env=pfo.env,
                        inherited=True,
