    return tok

def compute_id(long_name):
    if not long_name:
        return ""
    is_plus = long_name.startswith('+')
    stripped = long_name.lstrip('-+')
    stripped = stripped.replace('-', '_')
    if is_plus:
        return "plus_" + stripped
    return stripped

def notation_min_max(notation):
    # notation like "VALUE*", "FILE+", "VALUE?", "OXA~", "FILE", etc.
    s=notation
    if s.endswith('*'):
        return 0, 32767
    if s.endswith('+'):
        return 1, 32767
    if s.endswith('?'):
        return 0, 1
    if s.endswith('~'):
        return 1, 32767
    return 1,1

# Data structures simplified
class FlagOption:
    def __init__(self, **kwargs):
