        self.num_args=kwargs.get('num_args', [0,0] if kwargs.get('flag') else [1,1])
        self.delimiter=kwargs.get('delimiter')
        self.terminated=kwargs.get('terminated', False)
        self.prefixed=kwargs.get('prefixed', False)
