        self.choice=kwargs.get('choice')
        self.inherited=kwargs.get('inherited', False)

class Command:
    def __init__(self, name='', describe='', version=None):
        self.name=name
        self.describe=describe
        self.version=version
        self.aliases=[]
        self.flag_options=[]
        self.positionals=[]
        self.envs=[]
        self.subcommands={}  # name -> Command
        self.subcommands_list=[]
        self.command_fn=None
        self.metadata={}
        self.require_tools=[]
        self.dotenv=None
        self.combine_shorts=False
        self.inherit_flag_options=False
        self.default_subcommand=False
        self.symbol=None
        # For parsing, temporary storage of flag_options that are inherited etc.

def parse_file(file_path):
    with open(file_path, 'r', encoding='utf-8', errors='ignore') as f:
        content=f.read()
    lines=content.splitlines()
    funcs={}
    # extract functions
    func_def_re=re.compile(r'^\s*(?:function\s+)?([A-Za-z_][A-Za-z0-9_:]*)\s*\(\)\s*\{?')
    i=0
    while i < len(lines):
        line=lines[i]
        m=func_def_re.match(line)
        if m:
            name=m.group(1)
            idx=line.find('{', m.end()-1)
            if idx!=-1:
                brace=1
                for ch in line[idx+1:]:
                    if ch=='{':
                        brace+=1
                    elif ch=='}':
                        brace-=1
                if brace==0:
                    start=idx+1
                    end=line.rfind('}')
                    funcs[name]=line[start:end]
                    i+=1
                    continue
                else:
                    body_parts=[line[idx+1:]]
                    j=i+1
                    while j < len(lines) and brace>0:
                        l=lines[j]
                        for ch in l:
                            if ch=='{':
                                brace+=1
                            elif ch=='}':
                                brace-=1
                        if brace==0:
                            last_idx=l.rfind('}')
                            body_parts.append(l[:last_idx])
                            break
                        else:
                            body_parts.append(l)
                        j+=1
                    funcs[name]="\n".join(body_parts)
                    i=j+1
                    continue
        i+=1

    basename=os.path.basename(file_path)
    if basename.endswith('.sh'):
        basename=basename[:-3]
    root=Command(name=basename, describe='', version=None)
    pending=None

    def collect_continuation(start_idx):
        cont=[]
        j=start_idx
        while j < len(lines):
            l=lines[j]
            stripped=l.lstrip()
            if not stripped.startswith('#'):
                break
            after=stripped[1:].lstrip() if stripped.startswith('#') else stripped
            if after.startswith('@'):
                break
            cont.append(after)
            j+=1
        return cont, j

    i=0
    while i < len(lines):
        line=lines[i]
        tag_match=re.match(r'^\s*#\s*@(\w+)(.*)$', line)
        if tag_match:
            tag=tag_match.group(1)
            rest=tag_match.group(2).strip()
            cont, nxt=collect_continuation(i+1)
            if tag=='describe':
                target=pending if pending else root
                # combine rest + cont
                long_lines=cont[:]
                while long_lines and long_lines[0].strip()=="":
                    long_lines.pop(0)
                while long_lines and long_lines[-1].strip()=="":
                    long_lines.pop()
                long_clean="\n".join(long_lines)
                if rest and long_clean:
                    target.describe=rest+"\n\n"+long_clean
                elif rest:
                    target.describe=rest
                else:
                    target.describe=long_clean
                i=nxt
                continue
            elif tag=='meta':
                target=pending if pending else root
                if not rest:
                    i=nxt if cont else i+1
                    continue
                parts=rest.split(None,1)
                key=parts[0]
                value=parts[1] if len(parts)>1 else ""
                target.metadata[key]=value if value else None
                if key=='version':
                    target.version=value
                elif key=='dotenv':
                    target.dotenv=value if value else ".env"
                elif key=='combine-shorts':
                    target.combine_shorts=True
                elif key=='inherit-flag-options':
                    target.inherit_flag_options=True
                elif key=='require-tools':
                    tools=[t.strip() for t in value.split(',') if t.strip()]
                    target.require_tools.extend(tools)
                elif key=='default-subcommand':
                    target.default_subcommand=True
                elif key=='symbol':
                    target.symbol=value
                i=nxt if cont else i+1
                continue
            elif tag=='cmd':
                pending=Command(name='', describe=rest)
                if cont:
                    long_lines=cont[:]
                    while long_lines and long_lines[0].strip()=="":
                        long_lines.pop(0)
                    while long_lines and long_lines[-1].strip()=="":
                        long_lines.pop()
                    long_clean="\n".join(long_lines)
                    if rest and long_clean:
                        pending.describe=rest+"\n\n"+long_clean
                    elif long_clean:
                        pending.describe=long_clean
                    else:
                        pending.describe=rest
                i=nxt
                continue
            elif tag=='alias':
                aliases=[]
                for part in rest.split(','):
                    for sub in part.strip().split():
                        if sub:
                            aliases.append(sub)
                if pending:
                    pending.aliases.extend(aliases)
                else:
                    root.aliases.extend(aliases)
                i=nxt if cont else i+1
                continue
            elif tag in ('flag','option','arg','env'):
                # For these tags, rest contains definition plus maybe description, cont is long description
                # We need to parse based on tag
                tokens=rest.split()
                if not tokens:
                    i=nxt if cont else i+1
                    continue
                if tag in ('flag','option'):
                    # collect name tokens
                    name_tokens=[]
                    idx=0
                    while idx < len(tokens):
                        tok=tokens[idx]
                        if tok.startswith('-') or tok.startswith('+'):
                            name_tokens.append(tok)
                            idx+=1
                        else:
                            break
                    remaining=tokens[idx:]
                    env=None
                    notations=[]
                    desc_tokens=[]
                    j=0
                    while j < len(remaining):
                        rt=remaining[j]
                        if rt=='$$':
                            env='auto'
                            j+=1
                        elif rt.startswith('$'):
