# Helper to get choice values via bash
def get_choice_values(file_path, func_name, funcs):
    # Try to execute function via bash
    # Create a bash script that defines argc dummy and sources file and calls function
    # We have funcs dict, but to be safe we will source the file with dummy argc
    # The file may contain complex logic, but we can try to run bash -c with argc dummy
    bash_code = f'''
argc() {{ :; }}
source "{file_path}" >/dev/null 2>&1
if declare -F "{func_name}" >/dev/null 2>&1; then
  {func_name}
fi
'''
    try:
        result = subprocess.run(['bash', '-c', bash_code], stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, timeout=2)
        if result.returncode==0:
            # stdout contains choices each line
            choices = [line.strip() for line in result.stdout.splitlines() if line.strip()!='']
            return choices
        else:
            return []
    except Exception as e:
        return []

def get_default_value(file_path, func_name, funcs):
    bash_code = f'''
argc() {{ :; }}
source "{file_path}" >/dev/null 2>&1
if declare -F "{func_name}" >/dev/null 2>&1; then
  {func_name}
fi
'''
    try:
