def parse_file(file_path):
    with open(file_path, 'r', encoding='utf-8', errors='ignore') as f:
        content=f.read()
    lines=content.splitlines()
    funcs={}
    func_def_re=re.compile(r'^\s*(?:function\s+)?([A-Za-z_][A-Za-z0-9_:]*)\s*\(\)\s*\{?')
    i=0
    while i < len(lines):
        line=lines[i]
        m=func_def_re.match(line)
        if m:
            name=m.group(1)
            idx=line.find('{', m.end()-1)
            if idx!=-1:
                brace=1
                for ch in line[idx+1:]:
                    if ch=='{':
                        brace+=1
                    elif ch=='}':
                        brace-=1
                if brace==0:
                    start=idx+1
                    end=line.rfind('}')
                    funcs[name]=line[start:end]
                    i+=1
                    continue
                else:
                    body_parts=[line[idx+1:]]
                    j=i+1
                    while j < len(lines) and brace>0:
                        l=lines[j]
                        for ch in l:
                            if ch=='{':
                                brace+=1
                            elif ch=='}':
                                brace-=1
                        if brace==0:
                            last_idx=l.rfind('}')
                            body_parts.append(l[:last_idx])
                            break
                        else:
                            body_parts.append(l)
                        j+=1
                    funcs[name]="\n".join(body_parts)
                    i=j+1
                    continue
        i+=1

    basename=os.path.basename(file_path)
    if basename.endswith('.sh'):
        basename=basename[:-3]
    root=Command(name=basename, describe='', version=None)
    pending=None

    def collect_continuation(start_idx):
        cont=[]
        j=start_idx
        while j < len(lines):
            l=lines[j]
            stripped=l.lstrip()
            if not stripped.startswith('#'):
                break
            after=stripped[1:].lstrip() if stripped.startswith('#') else stripped
            if after.startswith('@'):
                break
            cont.append(after)
            j+=1
        return cont, j

    i=0
    while i < len(lines):
        line=lines[i]
        tag_match=re.match(r'^\s*#\s*@(\w+)(.*)$', line)
        if tag_match:
            tag=tag_match.group(1)
            rest=tag_match.group(2).strip()
            cont, nxt=collect_continuation(i+1)
            if tag=='describe':
                target=pending if pending else root
                long_lines=cont[:]
                while long_lines and long_lines[0].strip()=="":
                    long_lines.pop(0)
                while long_lines and long_lines[-1].strip()=="":
                    long_lines.pop()
                long_clean="\n".join(long_lines)
                if rest and long_clean:
                    target.describe=rest+"\n\n"+long_clean
                elif rest:
                    target.describe=rest
                else:
                    target.describe=long_clean
                i=nxt
                continue
            elif tag=='meta':
                target=pending if pending else root
