                if key=='version':
                    target.version=value
                elif key=='dotenv':
                    target.dotenv=value if value else ".env"
                elif key=='combine-shorts':
                    target.combine_shorts=True
                elif key=='inherit-flag-options':
                    target.inherit_flag_options=True
                elif key=='require-tools':
                    tools=[t.strip() for t in value.split(',') if t.strip()]
                    target.require_tools.extend(tools)
