# minimal parser for argc - we will reuse functions from earlier
import re, os

def split_name_and_suffix(token):
    token=token.strip()
    if not token:
        return "", ""
    m=re.match(r'^([\-+]+[A-Za-z0-9_]+(?:[-_][A-Za-z0-9_]+)*)', token)
    if m:
        base=m.group(1)
        suffix=token[len(base):]
        return base, suffix
    m=re.match(r'^([A-Za-z0-9_]+(?:[-_][A-Za-z0-9_]+)*)', token)
    if m:
        base=m.group(1)
        suffix=token[len(base):]
        return base, suffix
    return token, ""

def parse_suffix(suffix):
    prefixed=False
    assigned=False
    required=False
    multiple_occurs=False
    delimiter=None
    terminated=False
    default=None
    choice=None
    s=suffix
    if s.startswith('-'):
        prefixed=True
        s=s[1:]
    if s.startswith(':'):
        assigned=True
        s=s[1:]
    idx=0
    while idx < len(s):
        ch=s[idx]
        if ch=='!':
            required=True
            idx+=1
        elif ch=='+':
            required=True
            multiple_occurs=True
            idx+=1
        elif ch=='*':
            multiple_occurs=True
            idx+=1
        elif ch==',':
            delimiter=','
            idx+=1
        elif ch=='~':
            terminated=True
            idx+=1
        else:
            break
    s=s[idx:]
    if s.startswith('='):
        bracket_idx=s.find('[')
        if bracket_idx!=-1:
            default_part=s[1:bracket_idx]
            if default_part:
                if default_part.startswith('`') and default_part.endswith('`'):
                    default={"type":"Fn","value":default_part[1:-1]}
                else:
                    default={"type":"Value","value":default_part}
            s=s[bracket_idx:]
        else:
            default_part=s[1:]
            if default_part.startswith('`') and default_part.endswith('`'):
                default={"type":"Fn","value":default_part[1:-1]}
            else:
                default={"type":"Value","value":default_part}
            s=""
    if s.startswith('['):
        end_idx=s.find(']')
        if end_idx!=-1:
            inner=s[1:end_idx]
            # parse inner
            if inner.startswith('='):
                rest=inner[1:]
                parts=rest.split('|')
                if parts:
                    default={"type":"Value","value":parts[0]}
                    choice={"type":"Values","data":parts}
            elif '`' in inner:
                m=re.match(r'^(\?)?`([^`]+)`$', inner)
                if m:
                    q=m.group(1)
                    fn=m.group(2)
                    choice={"type":"Fn","data":[fn, False if q else True]}
            else:
                if '|' in inner:
                    parts=inner.split('|')
                    choice={"type":"Values","data":parts}
                elif inner:
                    choice={"type":"Values","data":[inner]}
            s=s[end_idx+1:]
    return {
        "prefixed": prefixed,
        "assigned": assigned,
        "required": required,
        "multiple_occurs": multiple_occurs,
        "delimiter": delimiter,
        "terminated": terminated,
        "default": default,
        "choice": choice,
        "remaining": s,
    }

