    if tok.startswith('<') and tok.endswith('>'):
        return tok[1:-1]
    return tok

def compute_id(long_name):
    if not long_name:
        return ""
    is_plus = long_name.startswith('+')
    stripped = long_name.lstrip('-+')
    stripped = stripped.replace('-', '_')
    if is_plus:
        return "plus_" + stripped
    return stripped

def notation_min_max(notation):
    s=notation
    if s.endswith('*'):
