            if default_part.startswith('`') and default_part.endswith('`'):
                default={"type":"Fn","value":default_part[1:-1]}
            else:
                default={"type":"Value","value":default_part}
            s=""
    if s.startswith('['):
        end_idx=s.find(']')
        if end_idx!=-1:
            inner=s[1:end_idx]
            if inner.startswith('='):
                rest=inner[1:]
                parts=rest.split('|')
